<template><section class="home-section"><div class="krds-container"><SectionHeader title="뉴스" more="더보기"/><div class="krds-tab-area layer"><div class="tab line"><ul role="tablist" aria-label="뉴스 분류"><li v-for="(tab, i) in newsTabs" :id="`tab-${i}`" :key="tab" role="tab" :aria-selected="active === i" :aria-controls="`news-panel-${i}`" :class="{ active: active === i }"><button type="button" class="btn-tab" @click="active = i">{{ tab }}<span v-if="active === i" class="sr-only"> 선택됨</span></button></li></ul></div><div class="tab-conts-wrap"><section :id="`news-panel-${active}`" class="tab-conts active" role="tabpanel" :aria-labelledby="`tab-${active}`"><div class="news-grid"><article v-for="item in visibleNews" :key="item.title" class="news-card"><div v-if="item.thumb" class="news-thumb" :class="item.thumb" role="img" :aria-label="`${item.title} 관련 이미지`"></div><div><span class="news-category">{{ item.category }}</span><h3>{{ item.title }}</h3><p>{{ item.description }}</p><a href="#" class="krds-btn small link basic">자세히보기 <i class="svg-icon ico-angle right"></i></a></div></article></div></section></div></div></div></section></template>
<script setup>import { computed, ref } from 'vue'; import SectionHeader from '@/components/common/SectionHeader.vue'; import { newsItems, newsTabs } from '@/data/homeData.js'; const active = ref(0); const visibleNews = computed(() => active.value === 0 ? newsItems : newsItems.filter(n => n.category === newsTabs[active.value]).length ? newsItems.filter(n => n.category === newsTabs[active.value]) : newsItems.slice(0, 2))</script>
